final class DictationScreen {
    let id = 18
    func makeReplay() -> () -> Void {
        return { [weak self] in
            guard let self else { print("Экран закрыт"); return }
            print("Повтор \(self.id)")
        }
    }
    deinit { print("Экран освобождён") }
}
var screen: DictationScreen? = DictationScreen()
let replay = screen!.makeReplay()
replay()
screen = nil
replay()

Сначала «Повтор 18», затем «Экран освобождён», затем «Экран закрыт». Исходник аварийно завершается при последнем обращении к освобождённому self.

