final class DictationHint {
    unowned let owner: DictationSession
    init(owner: DictationSession) { self.owner = owner }
    func show() { print(owner.id) }
}
final class DictationSession {
    let id = 18
    private lazy var hint = DictationHint(owner: self)
    func showHint() { hint.show() }
}
let session = DictationSession()
session.showHint()

Вывод 18. Подсказка не может пережить сессию через публичный интерфейс и используется при живом владельце. Если условие изменится, выбор нужно пересмотреть.

final class DictationScreen {
    let id = 18
    func makeProgress() -> () -> Void {
        return { [weak self] in
            guard let self else { print("Экран закрыт"); return }
            print("Прогресс \(self.id)")
        }
    }
    deinit { print("Экран освобождён") }
}
var screen: DictationScreen? = DictationScreen()
let replay = screen!.makeProgress()
replay()
screen = nil
replay()

Вывод: «Прогресс 18», «Экран освобождён», «Экран закрыт». Это другое событие диктанта с тем же контрактом позднего вызова.
